const output = [];

for (const item of items) {
  const d = item.json;

  const excelDate = d["OLTIMO Lubes & Chemicals Pvt. Ltd."];
  const party = d["__EMPTY"];
  const vchType = d["__EMPTY_1"];
  const vchNo = d["__EMPTY_2"];
  const debit = d["__EMPTY_3"] || 0;
  const credit = d["__EMPTY_4"] || 0;

  // Skip junk rows
  if (!party || typeof excelDate !== "number") continue;

  // We only want Sales (Tax Invoice) and Receipts
  if (!["Tax Invoice", "Receipt","Credit Note (Sale)"].includes(vchType)) continue;

  // Convert Excel date
  const orderDate = new Date((excelDate - 25569) * 86400 * 1000)
    .toISOString()
    .split("T")[0];

  output.push({
    order_date: orderDate,
    party_name: party,
    voucher_type: vchType,
    voucher_no: vchNo || null,
    bill_amount: vchType === "Tax Invoice" ? debit : null,
    payment_received: vchType === "Receipt" ||vchType === "Credit Note (Sale)"  ? credit : null,
    payment_mode: vchType === "Receipt" ? d["__EMPTY_2"] : null
  });
}


return output.map(o => ({ json: o }));

// Get all incoming items
const items = $input.all();

// Create a Map to track unique records
const uniqueMap = new Map();

for (const item of items) {

  const row = item.json;

  // Create unique key (change fields if needed)
  const key = `${row.order_date}_${row.party_name}_${row.payment_received}`;

  // Store only first occurrence
  if (!uniqueMap.has(key)) {
    uniqueMap.set(key, item);
  }
}

// Return only unique values
return Array.from(uniqueMap.values());

const newPayments = $('Remove_duplicates').all();
const paymentStatus = $('Payment_Status').all();

const normalize = v => String(v || '').trim().toLowerCase();
const num = v => isNaN(Number(v)) ? 0 : Number(v);

const normalizeDate = (value) => {
  if (!value || value === 'empty') return '';
  const d = new Date(value);
  if (isNaN(d)) return '';
  return d.toISOString().split('T')[0];
};

/************************************************
 * STEP 1️⃣ BUILD HASH SET FROM Payment_Status
 ************************************************/

const existingPayments = new Set();

for (const status of paymentStatus) {

  const party = normalize(
    status.json["Party Name"] ??
    status.json["party name"]
  );

  const amount = num(
    status.json["actual payment"] ??
    status.json["Actual Payment"] ??
    0
  );

  const date = normalizeDate(
    status.json["Payment Date"] && status.json["Payment Date"] !== 'empty'
      ? status.json["Payment Date"]
      : status.json["Part-Payment Date"]
  );

  if (!party || !amount || !date) continue;

  const key = `${party}|${date}|${amount}`;
  existingPayments.add(key);
}

/************************************************
 * STEP 2️⃣ FILTER NEW PAYMENTS
 ************************************************/

const output = [];

for (const payment of newPayments) {

  const party = normalize(payment.json.party_name);
  const amount = num(payment.json.payment_received);
  const date = normalizeDate(payment.json.order_date);

  if (!party || !amount || !date) {
    output.push(payment); // let settlement handle validation
    continue;
  }

  const key = `${party}|${date}|${amount}`;

  if (!existingPayments.has(key)) {
    output.push(payment);
  }
}

return output;

/************************************************
 * READ INPUTS
 ************************************************/
const bills = $items("Payment_Status").map(i => i.json);
const payments = $items("Not_Existing_payments").map(i => i.json);

/************************************************
 * HELPERS
 ************************************************/
const normalize = v => String(v || "").trim().toLowerCase();
const num = v => isNaN(Number(v)) ? 0 : Number(v);

const parseDate = v => {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d) ? null : d;
};

const iso = d => d ? d.toISOString().split("T")[0] : "";

/************************************************
 * STEP 1️⃣ NORMALIZE BILLS (SAFE COLUMN MATCH)
 ************************************************/
const billsByParty = {};

for (const b of bills) {

  const partyRaw =
    b["Party Name"] ??
    b["party name"] ??
    "";

  const party = normalize(partyRaw);

  const row = b.row_number;

  const billDate = parseDate(
    b["Order Date"] ??
    b["order date"]
  );

  const balanceRaw = num(
    b["balence"] ??
    b["Balence"] ??
    b["Balence Due"] ??
    0
  );

  const paid = num(
    b["payment"] ??
    b["Payment"] ??
    0
  );

  if (!party || !row || !billDate) continue;
  if (balanceRaw <= 0) continue;

  billsByParty[party] ??= [];
  billsByParty[party].push({
    row_number: row,
    party_name: partyRaw,
    bill_date: billDate,
    balance_due: balanceRaw,
    paid_so_far: paid,
  });
}

for (const p in billsByParty) {
  billsByParty[p].sort((a, b) => a.bill_date - b.bill_date);
}

/************************************************
 * STEP 2️⃣ NORMALIZE PAYMENTS
 ************************************************/
const paymentsByParty = {};

for (const p of payments) {

  const party = normalize(p.party_name);
  const paymentDate = parseDate(p.order_date);
  const amount = num(p.payment_received);

  if (!party || !paymentDate || amount <= 0) continue;

  paymentsByParty[party] ??= [];
  paymentsByParty[party].push({
    payment_date: paymentDate,
    amount,
    mode: p.payment_mode || "",
  });
}

for (const p in paymentsByParty) {
  paymentsByParty[p].sort((a, b) => a.payment_date - b.payment_date);
}

/************************************************
 * STEP 3️⃣ FIFO SETTLEMENT
 ************************************************/
const updates = [];

for (const party of Object.keys(billsByParty)) {

  if (!paymentsByParty[party]) continue;

  const partyBills = billsByParty[party];
  const partyPayments = paymentsByParty[party];

  let billIdx = 0;

  for (const payment of partyPayments) {

    let remaining = payment.amount;

    while (remaining > 0 && billIdx < partyBills.length) {

      const bill = partyBills[billIdx];

      // Prevent payment before bill date
      if (payment.payment_date < bill.bill_date) {
        break;
      }

      let settle = Math.min(remaining, bill.balance_due);
      let newBalance = bill.balance_due - settle;

      // auto close < 10
      if (newBalance < 10) {
        settle += newBalance;
        newBalance = 0;
      }

      updates.push({
        row_number: bill.row_number,
        "party name": bill.party_name,
        "Order Date": iso(bill.bill_date),
        "payment": bill.paid_so_far + settle,
        "balence": newBalance,
        "payment mode": payment.mode,
        "payment date": newBalance === 0 ? iso(payment.payment_date) : "",
        "part-payment date": newBalance > 0 ? iso(payment.payment_date) : "",
        "actual payment": payment.amount
      });

      bill.paid_so_far += settle;
      bill.balance_due = newBalance;
      remaining -= settle;

      if (bill.balance_due === 0) {
        billIdx++;
      } else {
        break;
      }
    }
  }
}

/************************************************
 * FINAL RETURN
 ************************************************/
if (updates.length === 0) {
  return [{ json: { status: "NO_UPDATES" } }];
}

return updates.map(u => ({ json: u }));

